mapper.select:
select ptd.id, grou.id 'groupsId', grou.name 'groupsName', grou.workshop_id 'workshop.id', shop.name 'workshop.name', grou.production_line_id 'productionLine.id', line.name 'productionLine.name', ptd.id AS 'machineToolId', ptd.mid, ptd.part_type, ptd.part_prod_mode, ptd.device_type 'deviceType.id', ptd.device_name, ptd.nc_system 'ncSystem.id', ptd.nc_file_format 'ncFileFormat.id', ptd.team_status, ptd.cutting_report_method, ptd.drill_report_method from mes_building_machine_part_team_detail ptd left join mes_building_groups grou on ptd.groups_id = grou.id and grou.bool_delete_enum=0 left join mes_building_production_line line on grou.production_line_id = line.id and line.bool_delete_enum=0 left join mes_building_workshop shop on line.workshop_id = shop.id and shop.bool_delete_enum=0
ptd.bool_delete_enum=0
AND ptd.id=#{id}
AND ptd.process_id=#{processId}
AND line.workshop_id=#{workshopId}
AND ptd.production_line_id=#{productionLineId}
AND ptd.organization_type=#{organizationType}
AND ptd.team_status=#{teamStatus}
AND ptd.part_prod_mode=#{partProdMode}
AND ptd.part_type=#{partType}
AND ptd.groups_id=#{groupsId}

select ptd.id, ptd.part_feature, ptd.groups_id, ptd.part_feature, shop.name 'workshop.name', line.id 'productionLine.id', line.name 'productionLine.name', ptd.id AS 'machineToolId', ptd.mid, ptd.part_type, CASE ptd.part_type WHEN 1 THEN '板材零件' WHEN 2 THEN '型材零件' ELSE '' END AS 'partTypeName', ptd.process_type, ptd.drill_method, ptd.part_prod_mode, ptd.device_type 'deviceType.id', processes.name 'deviceType.name', ptd.device_name, ptd.nc_system 'ncSystem.id', ptd.nc_file_format 'ncFileFormat.id', ptd.team_status, ptd.cutting_report_method, ptd.drill_report_method from mes_building_machine_part_team_detail ptd left join mes_building_production_line line on ptd.production_line_id = line.id and line.bool_delete_enum=0 left join mes_building_workshop shop on line.workshop_id = shop.id and shop.bool_delete_enum=0 left join mes_building_process processes on processes.id = ptd.device_type
ptd.bool_delete_enum=0
AND ptd.id=#{id}
AND ptd.process_id=#{processId}
AND line.workshop_id=#{workshopId}
AND ptd.production_line_id=#{productionLineId}
AND ptd.organization_type=#{organizationType}
AND ptd.team_status=#{teamStatus}
AND ptd.part_prod_mode=#{partProdMode}
AND ptd.part_type=#{partType}
AND ptd.groups_id=#{groupsId}
